+.frame {
+  position: absolute;
+  inset: 0;
+  overflow: hidden;
+  pointer-events: none;
+}
+
+.artwork {
+  width: 100%;
+  height: 100%;
+  animation: drift 20s ease-in-out infinite alternate;
+}
+
+.artwork > svg,
+.artwork > img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+}
+
+.light {
+  position: absolute;
+  inset: -10%;
+  background: radial-gradient(ellipse at 20% 20%, #fff3cf24, transparent 65%);
+  animation: light-drift 14s ease-in-out infinite alternate;
+}
+
+.frame[data-motion-paused="true"] > * {
+  animation-play-state: paused;
+}
+
+.toggle {
+  position: absolute;
+  top: 14px;
+  right: 14px;
+  border: 1px solid #dce1d0;
+  border-radius: 20px;
+  background: #fffdf6ed;
+  padding: 10px 14px;
+  min-height: 44px;
+  font-size: 11px;
+}
+
