+  from { transform: translate(-3%, -2%); opacity: .45; }
+  to { transform: translate(3%, 2%); opacity: .85; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .artwork,
+  .light { animation: none; }
+  .light,
