(() => {
  const frame = document.querySelector('[data-motion-paused]');
  const art = frame.firstElementChild;
  const animation = art.getAnimations()[0];
  if (!animation) throw Error('Artwork animation is missing');
  animation.pause(); animation.currentTime = 0;
  const start = getComputedStyle(art).transform;
  animation.currentTime = 20000;
  const end = getComputedStyle(art).transform;
  animation.play();
  const caption = document.querySelector('.picture-caption');
  return {animation: getComputedStyle(art).animationName, duration: getComputedStyle(art).animationDuration, changes: start !== end, start, end, clipped: getComputedStyle(frame).overflow, captionAnimation: getComputedStyle(caption).animationName, imageCount: frame.querySelectorAll('svg, img').length};
})()
