export async function post<T>(path: string, body: unknown, signal?: AbortSignal): Promise<T> {
  const res = await fetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body), signal });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.error || "Something went wrong. Please try again.");
  }
  return res.json();
}

import { TurnSchema, type Turn } from "@/lib/engine/schema";
import type { StreamedSegment, TurnEvent } from "@/lib/engine/streamSegments";

export async function streamTurn(state: unknown, signal: AbortSignal, onSegment: (segment: StreamedSegment) => void): Promise<Turn> {
  const res = await fetch("/api/turn", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ state }), signal });
  if (!res.ok) throw new Error((await res.json()).error || "Couldn't turn the page.");
  if (!res.body) throw new Error("The story stream is missing.");
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let turn: Turn | undefined;
  const consume = (line: string) => {
    if (!line.trim()) return;
    const event = JSON.parse(line) as TurnEvent;
    if (event.type === "error") throw new Error(event.error);
    if (event.type === "segment") onSegment(TurnSchema.shape.segments.element.parse(event));
    if (event.type === "turn") turn = TurnSchema.parse(event.turn);
  };
  try {
    for (;;) {
      const { done, value } = await reader.read();
      buffer += decoder.decode(value, { stream: !done });
      let end: number;
      while ((end = buffer.indexOf("\n")) !== -1) {
        consume(buffer.slice(0, end));
        buffer = buffer.slice(end + 1);
      }
      if (done) break;
    }
    consume(buffer);
    if (!turn) throw new Error("The story stopped before the page was complete.");
    return turn;
  } finally {
    void reader.cancel().catch(() => {});
    reader.releaseLock();
  }
}

async function speechResponse(text: string, voice: string, signal: AbortSignal): Promise<Response> {
  const res = await fetch("/api/tts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text, voice }), signal });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.error || "Couldn't load the voice.");
  }
  return res;
}

export async function speech(text: string, voice: string, signal: AbortSignal): Promise<Blob> {
  return (await speechResponse(text, voice, signal)).blob();
}

export interface SpeechAudio {
  blob: Promise<Blob>;
  play: () => Promise<void>;
}

/** Download once, play MP3 bytes immediately, and retain the complete recording for saves. */
export function speechAudio(text: string, voice: string, signal: AbortSignal): SpeechAudio {
  const response = speechResponse(text, voice, signal);
  const blob = response.then(res => res.clone().blob());
  void blob.catch(() => {});
  return {
    blob,
    async play() {
      if (typeof MediaSource === "undefined" || !MediaSource.isTypeSupported("audio/mpeg")) {
        return playBlob(await blob, signal);
      }
      return playStream(await response, signal);
    },
  };
}

function playStream(response: Response, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal.aborted) return reject(new DOMException("Stopped", "AbortError"));
    const source = new MediaSource();
    const url = URL.createObjectURL(source);
    const audio = new Audio(url);
    const reader = response.body!.getReader();
    let settled = false;
    const finish = (error?: unknown) => {
      if (settled) return;
      settled = true;
      signal.removeEventListener("abort", abort);
      audio.pause();
      audio.removeAttribute("src");
      audio.load();
      URL.revokeObjectURL(url);
      void reader.cancel().catch(() => {});
      if (error) reject(error); else resolve();
    };
    const abort = () => finish(new DOMException("Stopped", "AbortError"));
    signal.addEventListener("abort", abort, { once: true });
    audio.onended = () => finish();
    audio.onerror = () => finish(new Error("Audio couldn't play. Tap Continue to try again."));
    source.addEventListener("sourceopen", async () => {
      try {
        if (settled) return;
        const buffer = source.addSourceBuffer("audio/mpeg");
        for (;;) {
          const { done, value } = await reader.read();
          if (settled) return;
          if (done) break;
          await new Promise<void>((yes, no) => {
            const cleanup = () => {
              buffer.removeEventListener("updateend", updated);
              buffer.removeEventListener("error", failed);
              signal.removeEventListener("abort", stopped);
            };
            const updated = () => { cleanup(); yes(); };
            const failed = () => { cleanup(); no(new Error("Couldn't decode voice audio.")); };
            const stopped = () => { cleanup(); no(new DOMException("Stopped", "AbortError")); };
            buffer.addEventListener("updateend", updated, { once: true });
            buffer.addEventListener("error", failed, { once: true });
            signal.addEventListener("abort", stopped, { once: true });
            buffer.appendBuffer(value);
          });
        }
        if (!settled && source.readyState === "open") source.endOfStream();
      } catch (error) { finish(error); }
    }, { once: true });
    void audio.play().catch(finish);
  });
}

export function playBlob(blob: Blob, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal.aborted) return reject(new DOMException("Stopped", "AbortError"));
    const url = URL.createObjectURL(blob);
    const audio = new Audio(url);
    const finish = (err?: unknown) => {
      audio.pause();
      audio.removeAttribute("src");
      URL.revokeObjectURL(url);
      signal.removeEventListener("abort", abort);
      if (err) reject(err); else resolve();
    };
    const abort = () => finish(new DOMException("Stopped", "AbortError"));
    signal.addEventListener("abort", abort, { once: true });
    audio.onended = () => finish();
    audio.onerror = () => finish(new Error("Audio couldn't play. Tap Continue to try again."));
    audio.play().catch(finish);
  });
}

export class Microphone {
  private stream?: MediaStream;
  private socket?: WebSocket;
  private recorder?: MediaRecorder;
  private keepalive?: ReturnType<typeof setInterval>;
  private stopped = false;

  async start(onInterim: (text: string) => void, onFinal: (text: string) => void, onError: (message: string) => void) {
    if (!navigator.mediaDevices?.getUserMedia) throw new Error("Microphone needs HTTPS or localhost and a supported browser.");
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
    if (this.stopped) { this.stop(); return; }
    try {
      const { token } = await post<{ token: string }>("/api/deepgram-token", {});
      if (this.stopped) { this.stop(); return; }
      const params = new URLSearchParams({ model: "nova-3", language: "en-US", interim_results: "true", smart_format: "true", endpointing: "350", utterance_end_ms: "1000", vad_events: "true" });
      const socket = this.socket = new WebSocket(`wss://api.deepgram.com/v1/listen?${params}`, ["bearer", token]);
      await new Promise<void>((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error("Microphone connection timed out.")), 10000);
        socket.onopen = () => { clearTimeout(timeout); resolve(); };
        socket.onerror = () => { clearTimeout(timeout); reject(new Error("Couldn't connect to Deepgram.")); };
        socket.onclose = () => { clearTimeout(timeout); reject(new Error("Microphone connection closed.")); };
      });
      if (this.stopped) { this.stop(); return; }
      let pending = "";
      const flush = () => { if (pending.trim()) onFinal(pending.trim()); pending = ""; };
      socket.onmessage = (event) => {
        const msg = JSON.parse(event.data);
        const text = msg.channel?.alternatives?.[0]?.transcript;
        if (text) {
          onInterim(text);
          if (msg.is_final) pending += ` ${text}`;
        }
        if (msg.speech_final || msg.type === "UtteranceEnd") flush();
      };
      socket.onclose = () => { if (!this.stopped) { this.stop(); onError("The microphone disconnected. Turn Play mode on again to reconnect."); } };
      socket.onerror = () => onError("Microphone connection error.");
      const mimeType = ["audio/webm;codecs=opus", "audio/ogg;codecs=opus", "audio/mp4"].find(t => MediaRecorder.isTypeSupported(t));
      this.recorder = new MediaRecorder(this.stream, mimeType ? { mimeType } : undefined);
      this.recorder.ondataavailable = e => { if (e.data.size && socket.readyState === WebSocket.OPEN) socket.send(e.data); };
      this.recorder.start(100);
      this.keepalive = setInterval(() => { if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify({ type: "KeepAlive" })); }, 5000);
    } catch (err) { this.stop(); throw err; }
  }

  stop() {
    this.stopped = true;
    clearInterval(this.keepalive);
    if (this.recorder?.state === "recording") this.recorder.stop();
    this.stream?.getTracks().forEach(t => t.stop());
    this.socket?.close();
  }
}

const VIDEO_POLL_MS = 3000;
const VIDEO_TIMEOUT_MS = 5 * 60_000;

/** Turns a finished picture into a looping clip. Resolves undefined when clips are turned off. */
export async function animateScene(imageUrl: string, scene: string, signal: AbortSignal): Promise<Blob | undefined> {
  const job = await post<{ id?: string; disabled?: boolean }>("/api/video", { imageUrl, scene }, signal);
  if (job.disabled || !job.id) return undefined;
  const deadline = Date.now() + VIDEO_TIMEOUT_MS;
  while (Date.now() < deadline) {
    await new Promise<void>((resolve, reject) => {
      const timer = setTimeout(resolve, VIDEO_POLL_MS);
      signal.addEventListener("abort", () => { clearTimeout(timer); reject(new DOMException("Stopped", "AbortError")); }, { once: true });
    });
    const res = await fetch(`/api/video?id=${encodeURIComponent(job.id)}`, { signal });
    if (res.status === 202) continue;
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      throw new Error(data.error || "The moving picture couldn’t be made.");
    }
    return res.blob();
  }
  throw new Error("The moving picture took too long.");
}

import type { Mode, StoryDef, StoryState } from "@/lib/types";
import { initialState, applyTurn, addChildUtterance, findCharacter } from "@/lib/engine/reducer";
import { TurnSchema, type Turn } from "@/lib/engine/schema";
import type { StreamedSegment } from "@/lib/engine/streamSegments";
import { animateScene, Microphone, playBlob, post, speech, speechAudio, streamTurn, type SpeechAudio } from "./client";
import type { AdventurePage } from "@/lib/db";
import { isLikelyEcho } from "@/lib/engine/echo";

export interface SessionView {
  state: StoryState;
  pages: AdventurePage[];
  status: string;
  error: string;
  listening: boolean;
  imageBusy: boolean;
  videoBusy: boolean;
}
interface PreparedTurn {
  state: StoryState;
  controller: AbortController;
  segments: StreamedSegment[];
  audio: (SpeechAudio | undefined)[];
  done: Promise<Turn>;
  notify?: () => void;
}
export class StorySession {
  view: SessionView;
  private controller?: AbortController;
  private mic?: Microphone;
  private generation = 0;
  private timer?: ReturnType<typeof setTimeout>;
  private referenceUrl?: string;
  private imageJobs = new Set<Promise<void>>();
  private imageControllers = new Set<AbortController>();
  private videoJobs = 0;
  private closed = false;
  private paused = true;
  private pendingPage?: AdventurePage;
  private recentlySpoken = "";
  private spokenAt = 0;
  private snapshotting = false;
  private prefetched?: PreparedTurn;
  constructor(story: StoryDef, private update: (view: SessionView) => void, restored?: SessionView) {
    this.view = restored ? { ...restored, listening: false, imageBusy: false, videoBusy: false } : { state: initialState(story, "listen"), pages: [], status: "Ready when you are", error: "", listening: false, imageBusy: false, videoBusy: false };
  }
  private emit() { if (!this.closed) this.update({ ...this.view, pages: [...this.view.pages] }); }
  warmup() {
    if (!this.closed && !this.prefetched && this.view.state.mode === "listen" && !this.view.state.ended) {
      this.prefetched = this.prepare(this.view.state);
    }
  }
  private discardPrefetch() { this.prefetched?.controller.abort(); this.prefetched = undefined; }
  private prepare(state: StoryState): PreparedTurn {
    const controller = new AbortController();
    const prepared: PreparedTurn = { state, controller, segments: [], audio: [], done: undefined! };
    prepared.done = streamTurn(state, controller.signal, segment => {
      if (controller.signal.aborted) return;
      prepared.segments.push(segment);
      const character = findCharacter(state.characters, segment.speaker);
      // New characters need the final metadata before choosing their own voice.
      prepared.audio.push(segment.speaker === "narrator" || character
        ? speechAudio(segment.text, character?.voice ?? state.story.narratorVoice, controller.signal)
        : undefined);
      prepared.notify?.();
    }).then(turn => {
      const spoken = applyTurn(state, turn).spoken;
      prepared.segments = turn.segments;
      spoken.forEach((segment, i) => {
        prepared.audio[i] ??= speechAudio(segment.text, segment.voice, controller.signal);
      });
      return turn;
    });
    void prepared.done.catch(() => {});
    return prepared;
  }
  stopTurn() { clearTimeout(this.timer); this.generation++; this.controller?.abort(); }
  pause() { this.paused = true; this.stopTurn(); this.discardPrefetch(); this.view.status = "Paused"; this.emit(); }
  async mode(mode: Mode) {
    this.discardPrefetch();
    this.mic?.stop(); this.mic = undefined;
    this.view.state = { ...this.view.state, mode }; this.view.listening = false;
    this.emit();
    if (mode === "play") {
      const mic = this.mic = new Microphone();
      try {
        await mic.start(
          text => { if (!this.closed && this.mic === mic && !this.echo(text)) { this.stopTurn(); this.view.status = "I’m listening…"; this.emit(); } },
          text => { if (this.mic === mic && !this.echo(text)) void this.turn(text); },
          error => { this.view.error = error; this.view.listening = false; this.emit(); },
        );
        if (this.mic === mic && !this.closed) this.view.listening = true;
      } catch (e) { this.view.error = String((e as Error).message); }
      this.emit();
    }
  }
  private echo(text: string) { return Date.now() - this.spokenAt < 15000 && isLikelyEcho(text, this.recentlySpoken); }
  private async narrate(page: AdventurePage, controller: AbortController, current: () => boolean) {
    const loads = page.segments.map((s,i) => page.audio[i] ? Promise.resolve(page.audio[i]) : speech(s.text, s.voice, controller.signal));
    loads.forEach(p => { void p.catch(() => {}); });
    for (let i = 0; i < loads.length; i++) {
      const blob = await loads[i];
      if (!current()) return;
      page.audio[i] = blob;
      this.recentlySpoken = page.segments[i].text; this.spokenAt = Date.now() + page.segments[i].text.length * 90;
      this.view.status = `${page.segments[i].speakerName} is speaking`; this.emit();
      await playBlob(blob, controller.signal);
      this.spokenAt = Date.now();
    }
  }
  async turn(text?: string) {
    if (this.closed || this.snapshotting || (this.view.state.ended && !text && !this.pendingPage)) return;
    this.stopTurn(); this.paused = false;
    const generation = this.generation;
    let controller = this.controller = new AbortController();
    const current = () => !this.closed && generation === this.generation;
    if (text) this.view.state = { ...addChildUtterance(this.view.state, text), ended: false };
    this.view.error = ""; this.view.status = "Turning your ideas into a story…"; this.emit();
    try {
      if (!text && this.pendingPage) {
        const page = this.pendingPage;
        await this.narrate(page, controller, current);
        if (!current()) return;
        this.pendingPage = undefined;
        this.view.status = this.view.state.ended ? "The End. What a lovely adventure!" : "Ready for the next page"; this.emit();
        if (!this.view.state.ended) this.timer = setTimeout(() => { if (!this.paused) void this.turn(); }, 1200);
        return;
      }
      this.pendingPage = undefined;
      const base = this.view.state;
      if (text || this.prefetched?.state !== base) this.discardPrefetch();
      const prepared = this.prefetched ?? this.prepare(base);
      this.prefetched = undefined;
      controller = this.controller = prepared.controller;
      const previous = this.view.pages.at(-1);
      const page: AdventurePage = { segments: [], audio: [], image: previous?.image, video: previous?.video };
      let attached = false;
      let queued = 0;
      let playback = Promise.resolve();
      const display = (turn: Turn) => {
        const applied = applyTurn(base, turn);
        this.view.state = { ...applied.state, mode: this.view.state.mode };
        page.segments = applied.spoken;
        if (!attached) {
          attached = true; this.pendingPage = page; this.view.pages.push(page);
        }
        this.emit();
      };
      const schedule = () => {
        while (queued < page.segments.length && prepared.audio[queued]) {
          const i = queued++;
          const resource = prepared.audio[i]!;
          void resource.blob.then(blob => { if (current()) page.audio[i] = blob; }).catch(() => {});
          playback = playback.then(async () => {
            if (!current()) return;
            const segment = page.segments[i];
            this.recentlySpoken = segment.text; this.spokenAt = Date.now() + segment.text.length * 90;
            this.view.status = `${segment.speakerName} is speaking`; this.emit();
            await resource.play();
            page.audio[i] = await resource.blob;
            this.spokenAt = Date.now();
          });
          void playback.catch(() => {});
        }
      };
      prepared.notify = () => {
        if (!current()) return;
        display(TurnSchema.parse({ segments: prepared.segments }));
        schedule();
      };
      if (prepared.segments.length) prepared.notify();
      const turn = await prepared.done;
      if (!current()) return;
      display(turn);
      page.scene = turn.imagePrompt ?? undefined;
      if (turn.imagePrompt) this.illustrate(page, turn.imagePrompt);
      schedule();
      // Generate one page ahead while the current narration is playing.
      this.warmup();
      await playback;
      if (!current()) return;
      this.pendingPage = undefined;
      this.view.status = this.view.state.ended ? "The End. What a lovely adventure!" : turn.awaitChild ? "What happens next? Tell me!" : "A little more magic…"; this.emit();
      if (!this.view.state.ended && !(turn.awaitChild && this.view.state.mode === "play")) {
        this.timer = setTimeout(() => { if (!this.paused) void this.turn(); }, 1200);
      }
    } catch (e) {
      if (current() && (e as Error).name !== "AbortError") { controller.abort(); this.discardPrefetch(); this.view.error = (e as Error).message; this.view.status = "Let’s try that again"; this.emit(); }
    }
  }
  private illustrate(page: AdventurePage, scene: string) {
    const controller = new AbortController();
    this.imageControllers.add(controller);
    this.view.imageBusy = true; this.emit();
    const job = (async () => {
      try {
        const data = await post<{ url: string; dataUri: string }>("/api/image", { scene, artStyle: this.view.state.story.artStyle, characters: this.view.state.characters, referenceUrl: this.referenceUrl }, controller.signal);
        if (this.closed) return;
        const image = page.image = await (await fetch(data.dataUri)).blob();
        page.video = undefined;
        if (this.view.pages.at(-1) === page) this.referenceUrl = data.url;
        this.animate(image, data.url, scene);
      } catch (e) { if (!this.closed && (e as Error).name !== "AbortError") this.view.error = `Illustration: ${(e as Error).message}`; }
    })();
    this.imageJobs.add(job);
    void job.finally(() => { this.imageJobs.delete(job); this.imageControllers.delete(controller); this.view.imageBusy = this.imageJobs.size > 0; this.emit(); });
  }
  private animate(image: Blob, imageUrl: string, scene: string) {
    const controller = new AbortController();
    this.imageControllers.add(controller);
    this.videoJobs++; this.view.videoBusy = true; this.emit();
    void animateScene(imageUrl, scene, controller.signal)
      .then(video => {
        if (!video || this.closed) return;
        // Later pages that reuse this picture should move too.
        for (const p of this.view.pages) if (p.image === image) p.video = video;
      })
      .catch(e => { if ((e as Error).name !== "AbortError") console.warn("Scene animation failed:", e); })
      .finally(() => { this.imageControllers.delete(controller); this.videoJobs--; this.view.videoBusy = this.videoJobs > 0; this.emit(); });
  }
  async snapshot() {
    this.snapshotting = true;
    this.pause();
    this.mic?.stop(); this.mic = undefined; this.view.listening = false; this.emit();
    try {
      await Promise.all([...this.imageJobs]);
      // Interrupted pages still need complete audio for offline replay.
      for (const page of this.view.pages) {
        for (let i = 0; i < page.segments.length; i++) {
          if (!page.audio[i]) {
            const s = page.segments[i];
            page.audio[i] = await speech(s.text, s.voice, AbortSignal.timeout(30000));
          }
        }
      }
      return structuredClone({ story: this.view.state.story, state: this.view.state, pages: this.view.pages });
    } finally { this.snapshotting = false; }
  }
  close() {
    this.closed = true; this.stopTurn(); this.discardPrefetch(); this.mic?.stop();
    this.imageControllers.forEach(c => c.abort());
  }
}

import { openDB, type DBSchema } from "idb";
import type { SpokenSegment, StoryDef, StoryState } from "@/lib/types";

export interface AdventurePage {
  segments: SpokenSegment[];
  audio: Blob[];
  image?: Blob;
  video?: Blob;
  scene?: string;
}
export interface Adventure {
  id: string;
  title: string;
  createdAt: number;
  story: StoryDef;
  state: StoryState;
  pages: AdventurePage[];
}
interface Shelf extends DBSchema {
  adventures: { key: string; value: Adventure };
}
const db = () => openDB<Shelf>("onceupon", 1, { upgrade(db) { db.createObjectStore("adventures", { keyPath: "id" }); } });
export async function saveAdventure(adventure: Omit<Adventure, "id" | "createdAt">) {
  const copy = { ...adventure, id: crypto.randomUUID(), createdAt: Date.now() };
  await (await db()).put("adventures", copy);
  return copy.id;
}
export async function listAdventures() { return (await (await db()).getAll("adventures")).sort((a,b) => b.createdAt - a.createdAt); }
export async function getAdventure(id: string) { return (await db()).get("adventures", id); }

