"use client";
import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import type { StoryDef } from "@/lib/types";
import { StorySession, type SessionView } from "@/lib/audio/session";
import { saveAdventure } from "@/lib/db";
import { initialState } from "@/lib/engine/reducer";
import Scene from "./Scene";
import BlobImage from "./BlobImage";
import BlobVideo from "./BlobVideo";
export default function StoryPlayer({ story }: { story: StoryDef }) {
  const session = useRef<StorySession | null>(null);
  const [view, setView] = useState<SessionView>(() => ({ state: initialState(story, "listen"), pages: [], status: "Ready when you are", error: "", listening: false, imageBusy: false, videoBusy: false }));
  const latest = useRef(view);
  const [text, setText] = useState("");
  const [notice, setNotice] = useState("");
  const [saving, setSaving] = useState(false);
  useEffect(() => { const s = new StorySession(story, next => { latest.current = next; setView(next); }, latest.current); session.current = s; const warmup = setTimeout(() => s.warmup(), 100); return () => { clearTimeout(warmup); s.close(); session.current = null; }; }, [story]);
  const page = view?.pages.at(-1);
  async function save() {
    if (!session.current) return;
    setSaving(true);
    try { const snapshot = await session.current.snapshot(); await saveAdventure({ ...snapshot, title: `${story.title} · My version` }); setNotice("Saved! Your original story is still on the shelf."); }
    catch { setNotice("Couldn’t save. Your browser may be out of storage or have storage disabled."); }
    finally { setSaving(false); }
  }
  return <main className="reader"><Link className="back-link" href="/">← Back to the story shelf</Link><div className="reader-heading"><div><p className="eyebrow">YOUR NEXT CHAPTER</p><h1>{story.title}</h1></div><button className="button secondary" disabled={!page || saving} onClick={save}>{saving ? "Saving the magic…" : "♡ Save this version"}</button></div><div className="reader-grid"><section className="picture-panel">{page?.image ? <BlobImage blob={page.image} alt={page.scene || story.setting}/> : <Scene kind={story.id}/>}{page?.video && <BlobVideo blob={page.video} label={page.scene || story.setting}/>}<span className="picture-caption">{view?.imageBusy ? "✧ The page is changing…" : view?.videoBusy && !page?.video ? "✧ The picture is coming to life…" : `Chapter ${(view?.state.beatIndex ?? 0) + 1} · ${story.beats[view?.state.beatIndex ?? 0]?.title}`}</span></section><section className="reading-panel"><div className="mode-switch"><button aria-pressed={view?.state.mode === "listen"} onClick={() => void session.current?.mode("listen")}>♫ Listen</button><button aria-pressed={view?.state.mode === "play"} onClick={() => void session.current?.mode("play")}>◉ Play & talk</button></div><p className={`status ${view?.listening ? "listening" : ""}`} role="status">{view?.listening && <span className="live-dot"/>}{view?.status ?? "Opening your story…"}</p><div className="narration" aria-live="polite">{page ? page.segments.map((s,i) => <div key={i}><span className="speaker">{s.speakerName}</span><p>{s.text}</p></div>) : <><h2>Once upon a time…</h2><p>{story.blurb}</p><p className="muted small">Choose Listen to sit back, or Play & talk to jump into the adventure. Headphones help the story hear just your voice.</p></>}</div><div className="playback-controls"><button className="button primary" onClick={() => void session.current?.turn()} disabled={view?.state.ended}>{page ? "Continue →" : "Begin the story →"}</button><button className="button secondary" onClick={() => session.current?.pause()}>Pause</button></div>{view?.state.ended && <Link href="/" className="back-link">Find another adventure →</Link>}</section></div><div className="interaction-bar"><span className="mic-symbol">✧</span><form onSubmit={e => { e.preventDefault(); if (text.trim()) { void session.current?.turn(text.trim()); setText(""); } }}><label htmlFor="story-idea">{view?.listening ? "Your microphone is on. Jump in anytime!" : "A little idea can change everything."}</label><div className="input-row"><input id="story-idea" value={text} maxLength={600} onChange={e => setText(e.target.value)} placeholder='Try “The tortoise has roller skates!”'/><button type="submit" aria-label="Add your idea" disabled={!text.trim()}>↑</button></div></form><p>Talk to a character.<br/>Dream up a twist.<br/>Make it yours.</p></div>{view?.error && <p className="error" role="alert">{view.error}</p>}{notice && <p className="notice" role="status">{notice} <Link href="/adventures">My adventures →</Link></p>}<details className="transcript"><summary>Our adventure so far</summary>{view?.state.log.map((e,i) => <p key={i}><strong>{e.kind === "child" ? "You" : e.speaker}:</strong> {e.text}</p>)}</details></main>;
}

"use client";
import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { getAdventure, type Adventure } from "@/lib/db";
import { playBlob } from "@/lib/audio/client";
import BlobImage from "./BlobImage";
import BlobVideo from "./BlobVideo";
import Scene from "./Scene";
export default function Replay({ id }: { id: string }) {
  const [adventure,setAdventure] = useState<Adventure>();
  const [error,setError] = useState("");
  const [index,setIndex] = useState(0);
  const [playing,setPlaying] = useState(false);
  const controller = useRef<AbortController | null>(null);
  useEffect(() => {
    let active = true;
    getAdventure(id).then(a => { if (active) { if (a) setAdventure(a); else setError("This adventure isn’t on this browser’s shelf."); } }).catch(() => { if (active) setError("Couldn’t open this saved adventure."); });
    return () => { active = false; controller.current?.abort(); };
  }, [id]);
  function pause() { controller.current?.abort(); setPlaying(false); }
  async function play() {
    if (!adventure) return;
    pause(); const c = controller.current = new AbortController(); setPlaying(true); setError("");
    try {
      for (let p = index; p < adventure.pages.length; p++) {
        setIndex(p);
        for (const audio of adventure.pages[p].audio) if (audio) await playBlob(audio,c.signal);
        if (!adventure.pages[p].audio.length) { setError("No audio was saved for this page. You can still read it."); break; }
      }
    } catch (e) { if (!c.signal.aborted) setError((e as Error).message); }
    finally { if (!c.signal.aborted) setPlaying(false); }
  }
  const page = adventure?.pages[index];
  return <main className="reader"><Link className="back-link" href="/adventures">← My adventures</Link><h1>{adventure?.title || "Your saved adventure"}</h1>{page && <><div className="reader-grid"><section className="picture-panel">{page.image ? <BlobImage blob={page.image} alt={page.scene || adventure!.story.setting}/> : <Scene kind={adventure!.story.id}/>}{page.video && <BlobVideo blob={page.video} label={page.scene || adventure!.story.setting}/>}<span className="picture-caption">Page {index+1} of {adventure!.pages.length}</span></section><section className="reading-panel"><p className="eyebrow">JUST HOW YOU IMAGINED IT</p><div className="narration">{page.segments.map((s,i) => <div key={i}><span className="speaker">{s.speakerName}</span><p>{s.text}</p></div>)}</div><div className="playback-controls"><button className="button primary" onClick={() => playing ? pause() : void play()}>{playing ? "Pause" : "♫ Replay narration"}</button><button className="button secondary" disabled={index === 0} onClick={() => { pause(); setIndex(index-1); }}>←</button><button className="button secondary" disabled={index >= adventure!.pages.length-1} onClick={() => { pause(); setIndex(index+1); }}>→</button></div></section></div><p className="storage-note">Your saved version. Replaying doesn’t use the microphone or call the AI services.</p></>}{error && <p className="error" role="alert">{error}</p>}</main>;
}

